  match r, ph with
  | 1, 0 => farm1_0_1RB1LC_0LA1RB_1LD1LD_1LA0RB
  | _, _ => farm1_0_1RB1LC_0LA1RB_1LD1LD_1LA0RB  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1LC_0LA1RB_1LD1LD_1LA0RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1LC_0LA1RB_1LD1LD_1LA0RB (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

