  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWin 3;SCycL 3 0;SWinL 7]
  | 1, (StC, S0) => [SWin 3;SCycL 3 0;SWinL 2]
  | 1, (StC, S1) => [SWin 2]
  | 1, (StD, S0) => [SWin 3]
  | 1, (StD, S1) => [SWin 3;SCycL 3 0;SWin 1;SWinL 9;SCycR 3;SWin 6]
  | _, _ => []
  end.

