Lemma farm_sound_1RB1LC_0LA1RD_0LD1LA_1LA0RB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB1LC_0LA1RD_0LD1LA_1LA0RB r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
