Definition iarm_1RB1LC_0LC1RB_1LA1LD_1RD0RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LC1RB_1LA1LD_1RD0RB
  | 0, 1 => iarm0_1_1RB1LC_0LC1RB_1LA1LD_1RD0RB
  | 1, 0 => iarm1_0_1RB1LC_0LC1RB_1LA1LD_1RD0RB
  | 1, 1 => iarm1_1_1RB1LC_0LC1RB_1LA1LD_1RD0RB
  | _, _ => iarm0_0_1RB1LC_0LC1RB_1LA1LD_1RD0RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_0LC1RB_1LA1LD_1RD0RB : LRule :=
