Definition iarm_1RB1LC_0LC1RB_1LD0RB_1LA0RC (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LC1RB_1LD0RB_1LA0RC
  | 0, 1 => iarm0_1_1RB1LC_0LC1RB_1LD0RB_1LA0RC
  | 1, 0 => iarm1_0_1RB1LC_0LC1RB_1LD0RB_1LA0RC
  | 1, 1 => iarm1_1_1RB1LC_0LC1RB_1LD0RB_1LA0RC
  | _, _ => iarm0_0_1RB1LC_0LC1RB_1LD0RB_1LA0RC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

