  match r, ph with
  | 1, 0 => farm1_0_1RB1LC_0LC1RD_1LA0RB_1RC1RB
  | _, _ => farm1_0_1RB1LC_0LC1RD_1LA0RB_1RC1RB  (* unreachable: 0 < r < N0 + st *)
  end.

