  | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S0 DR StC
  | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DL StA
  | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S0 DL StC
  | StD, S1 => mk S0 DR StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1LC_0RC0RD_1LA0LA_0LC0RD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1LC_0RC0RD_1LA0LA_0LC0RD pins_1RB1LC_0RC0RD_1LA0LA_0LC0RD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LC_0RC0RD_1LA0LA_0LC0RD : Fam := mkFam 2 [[S0;S0];[S0;S1]] [] [[S1;S1];[S0;S1;S1;S1;S1]] Binary 1 [mkFill 0 [] 0 [] 1;mkFill 2 [] 0 [1] 0] StD S0 true [].
Local Notation FAM := fam_1RB1LC_0RC0RD_1LA0LA_0LC0RD.

(** ** The ladder, as DATA

    5 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LC_0RC0RD_1LA0LA_0LC0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1LC_0RC0RD_1LA0LA_0LC0RD.

Definition rules_1RB1LC_0RC0RD_1LA0LA_0LC0RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_0RC0RD_1LA0LA_0LC0RD.

Lemma ladder_ok_1RB1LC_0RC0RD_1LA0LA_0LC0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_0RC0RD_1LA0LA_0LC0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_0RC0RD_1LA0LA_0LC0RD. Qed.

(** ** The arms, as DATA

