(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LC_1LA1RD_0RD0LA_1RA1RB : NeverQuasiHaltsTr tm_1RB1LC_1LA1RD_0RD0LA_1RA1RB.
Proof.
  apply (boardph_neverqhtr tm_1RB1LC_1LA1RD_0RD0LA_1RA1RB pins_1RB1LC_1LA1RD_0RD0LA_1RA1RB FAM 1
                           iarm_1RB1LC_1LA1RD_0RD0LA_1RA1RB 0 1
                           farm_1RB1LC_1LA1RD_0RD0LA_1RA1RB 1 1
                           fm1_1RB1LC_1LA1RD_0RD0LA_1RA1RB fm2_1RB1LC_1LA1RD_0RD0LA_1RA1RB 0 vis_1RB1LC_1LA1RD_0RD0LA_1RA1RB
                           [1] 0 3).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
