(** ** What this board establishes

    21 of 21 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 21 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD : LRule :=
  mkLRule (mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 [])) 4 4.
Definition ch_iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD : list rstep := [RB (SRotL 1);RB (SWin 1);RB (SCycL 2 0);RB (SWin 2);RB (SCycR 2);RB (SWin 1);RB (SUnrotL 1)].
Lemma ok_iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD :
  check_arm tm false true rules iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD
            ch_iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LC_1RC1LB_1LA0RD_0LA1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD
  | _, _ => iarm0_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S0] [S1;S0] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 [])) 4 12.
Definition ch_farm1_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWin 4);RB (SWinL 4);RB (SCycR 2);RB (SWin 2)].
Lemma ok_farm1_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD :
  check_arm tm true true rules farm1_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD
            ch_farm1_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_1_1RB1LC_1RC1LB_1LA0RD_0LA1RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S0] [S1;S0] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 [])) 4 10.
Definition ch_farm1_1_1RB1LC_1RC1LB_1LA0RD_0LA1RD : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWinL 6);RB (SCycR 2);RB (SWin 2)].
Lemma ok_farm1_1_1RB1LC_1RC1LB_1LA0RD_0LA1RD :
  check_arm tm true true rules farm1_1_1RB1LC_1RC1LB_1LA0RD_0LA1RD
            ch_farm1_1_1RB1LC_1RC1LB_1LA0RD_0LA1RD = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1LC_1RC1LB_1LA0RD_0LA1RD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1LC_1RC1LB_1LA0RD_0LA1RD
  | 1, 1 => farm1_1_1RB1LC_1RC1LB_1LA0RD_0LA1RD
