          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S0;S1])) 4 8.
Definition ch_iarm0_1_1RB1LC_1RC1RA_1LB0LD_0RB1LD : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 2)].
